import{_ as e,o as a,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Combat Actions and Special Attacks","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/combat/actions.md","filePath":"en/game-design/combat/actions.md"}'),n={name:"en/game-design/combat/actions.md"};function o(d,t,s,c,l,m){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="combat-actions-and-special-attacks" tabindex="-1">Combat Actions and Special Attacks <a class="header-anchor" href="#combat-actions-and-special-attacks" aria-label="Permalink to &quot;Combat Actions and Special Attacks&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> Numeric examples are prototype hypotheses, not final balance. <strong>Implementation/availability:</strong> not established for these mechanics. <strong>Verification:</strong> documentation review, no playable prototype. <strong>Reviewed:</strong> 2026-10-09, Batch 05.</p><p><a href="/Syrolands-Public/en/guide/combat/special-attacks.html">Player guide</a> · <a href="/Syrolands-Public/en/game-design/combat/overview.html">Combat foundations</a> · <a href="/Syrolands-Public/en/game-design/combat/variable-registry.html">Combat Variable Registry</a></p><h2 id="a-shared-action-vocabulary" tabindex="-1">A shared action vocabulary <a class="header-anchor" href="#a-shared-action-vocabulary" aria-label="Permalink to &quot;A shared action vocabulary&quot;">​</a></h2><p>Use <strong>Special Attack (SA)</strong> as shorthand for learned special combat techniques; Combat Action is the broader schema including basic attacks and defensive responses. Skill supplies capability, technique supplies knowledge, Familiarity supplies fluency, Prepared Repertoire supplies ready options and player execution applies them.</p><table tabindex="0"><thead><tr><th>Category</th><th>Initial content-budget direction</th><th>Examples only</th></tr></thead><tbody><tr><td>Weapon-specific SA</td><td>Approximately 4 per weapon</td><td>War Hammer: Heavy Blow, Crushing Arc; other entries TBD</td></tr><tr><td>Family SA</td><td>Approximately 3 per weapon family</td><td>Mace Fighting: short Stun concept; other entries TBD</td></tr><tr><td>Universal action</td><td>Small shared martial set</td><td>Brace, Parry and other eligible defensive responses</td></tr></tbody></table><p>These are content budgets, not fixed slots, a complete catalogue, guaranteed universal eligibility or final effect definitions. Stun duration and every damage/trauma number remain unresolved.</p><h2 id="learning-familiarity-and-prepared-options" tabindex="-1">Learning, Familiarity and prepared options <a class="header-anchor" href="#learning-familiarity-and-prepared-options" aria-label="Permalink to &quot;Learning, Familiarity and prepared options&quot;">​</a></h2><p>Skill level alone does not award SAs. Trainers, academies, martial schools, factions, books/manuals, masters, exploration, challenges/competitions and later-permitted player teaching can transmit them. <a href="/Syrolands-Public/en/game-design/characters/familiarity.html">Shared Familiarity</a> normalizes <strong>Learned → Practiced → Mastered</strong>, permanent acquisition and decaying fluency for combat and spell patterns.</p><p>An initial Prepared Combat Repertoire UX prototype uses <strong>5 SA slots</strong>, not an accepted cap. A warrior may know more than are prepared. Do not bind five slots to INT: small extra capacity, faster changes or support for complex techniques are later possibilities, and INT must not become a mandatory warrior tax. Prepared techniques might lose fluency more slowly; rules remain unresolved. Being unprepared or incompatible is distinct from forgetting knowledge; access/preparation changes during combat need design.</p><h2 id="canonical-action-schema" tabindex="-1">Canonical action schema <a class="header-anchor" href="#canonical-action-schema" aria-label="Permalink to &quot;Canonical action schema&quot;">​</a></h2><p>Every action should fill relevant fields or explicitly mark them Unresolved / not applicable. This is a design record, not a database or network schema.</p><table tabindex="0"><thead><tr><th>Field</th><th>What the action must specify</th></tr></thead><tbody><tr><td>Name</td><td>Recognizable action identity</td></tr><tr><td>Action family</td><td>Basic, weapon-specific, family or universal/defensive classification</td></tr><tr><td>Weapon/family eligibility</td><td>Compatible equipment and family constraints</td></tr><tr><td>Required learned technique</td><td>Knowledge prerequisite; none only if explicitly appropriate</td></tr><tr><td>Reach</td><td>Physical maximum for this action</td></tr><tr><td>Minimum/effective range</td><td>Too-close limit and useful/sweet-spot bands</td></tr><tr><td>Spatial footprint</td><td>Region, arc, line, area or other justified shape</td></tr><tr><td>Stamina cost</td><td>Commitment and charging stages; no value assigned</td></tr><tr><td>Wind-up</td><td>Preparation before active execution</td></tr><tr><td>Active window</td><td>Interval when authoritative contact/effect may resolve</td></tr><tr><td>Recovery</td><td>Restrictions before subsequent actions</td></tr><tr><td>Accuracy modifier</td><td>Hit/placement chance contribution, distinct from automatic SA activation failure</td></tr><tr><td>Handling modifier</td><td>Cost/recovery/control contribution</td></tr><tr><td>Consistency modifier</td><td>Repeatability/variance contribution</td></tr><tr><td>Damage/trauma profile</td><td>Global damage versus local trauma behavior and type</td></tr><tr><td>Targeting profile</td><td>Intended targets/regions; intent is not guaranteed impact</td></tr><tr><td>Movement allowed</td><td>Movement restrictions across phases</td></tr><tr><td>Interruptibility</td><td>What can disrupt which phase; resulting state/cost unresolved</td></tr><tr><td>Telegraph</td><td>Animation/posture/sound and permitted information cues</td></tr><tr><td>Counter relationships</td><td>Compatible responses, feints, flanks and matchup limits</td></tr><tr><td>Familiarity effects</td><td>Qualitative execution changes by shared tier</td></tr><tr><td>Legacy behavior</td><td>Queued swing or immediate defense; invalidation rules</td></tr><tr><td>Modern behavior</td><td>Triggered initiation and own preparation/phase constraints</td></tr></tbody></table><h3 id="example-records-deliberately-incomplete" tabindex="-1">Example records, deliberately incomplete <a class="header-anchor" href="#example-records-deliberately-incomplete" aria-label="Permalink to &quot;Example records, deliberately incomplete&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Scope</th><th>Timing/resource/spatial direction</th><th>Counters / remaining fields</th></tr></thead><tbody><tr><td>Stun</td><td>Mace family SA candidate</td><td>Short stun idea; stamina, range, wind-up, active and recovery TBD</td><td>Matchups, interruptibility, telegraph, accuracy, damage/trauma and learning prerequisites TBD</td></tr><tr><td>Heavy Blow</td><td>War Hammer SA candidate</td><td>Committed blow; no final costs or phase durations</td><td>Handling, region profile, movement and counters TBD</td></tr><tr><td>Crushing Arc</td><td>War Hammer SA candidate</td><td>Arc/footprint to evaluate, potentially extended physical reach</td><td>Target count, friendly contacts, transmission and animation feasibility TBD</td></tr><tr><td>Brace</td><td>Defensive candidate</td><td>Short stamina-funded stance/window with restricted movement</td><td>Compatible committed attacks only; feint, delay, flank or incompatible action can defeat it</td></tr></tbody></table><p>The general schema governs all examples; missing fields are not defaults. Offensive examples follow each mode&#39;s queue/trigger rule; defensive Brace is immediate in both.</p><h2 id="defensive-actions-and-information" tabindex="-1">Defensive actions and information <a class="header-anchor" href="#defensive-actions-and-information" aria-label="Permalink to &quot;Defensive actions and information&quot;">​</a></h2><p>Brace, Parry, Riposte, Counter-thrust, Dodge/Step and Interrupt are candidate immediate responses in both modes, subject to their own requirements. Immediate input does not waive wind-up, recovery or eligibility.</p><p>Brace might last <strong>about 2 seconds as a prototype illustration only</strong>. It costs stamina and restricts movement. A compatible committed attack arriving in the window may have damage/trauma reduced and provoke a strong counter emphasizing penetration/momentum. If no attack arrives, stamina/time/recovery are wasted. Feint, delay, flank and incompatible attacks are counterplay, not guarantees or formulas.</p><table tabindex="0"><thead><tr><th>Information</th><th>Proposed reading</th></tr></thead><tbody><tr><td>All players</td><td>Animation, posture and sound</td></tr><tr><td>Mid Tactics</td><td>Generic cue such as “preparing a committed attack”</td></tr><tr><td>Higher Tactics</td><td>Action-family cue such as “charging overhead strike”</td></tr></tbody></table><p>Do not reveal “press Brace now” solutions. Exact thresholds, disclosure, accessibility and deceptive telegraphs remain undecided. Tactics improves information rather than secretly deciding the response.</p><h2 id="failure-and-balance" tabindex="-1">Failure and balance <a class="header-anchor" href="#failure-and-balance" aria-label="Permalink to &quot;Failure and balance&quot;">​</a></h2><p>Prefer timing, range, orientation, stamina, recovery, counterplay and incompatible matchups as failure reasons over arbitrary “SA activation failed” RNG after valid conditions. This does not abolish existing hit/miss or magic fizzle: <a href="/Syrolands-Public/en/game-design/combat/variable-registry.html">Accuracy and Consistency</a> remain separate concepts. Familiarity should improve execution with modest benefits, not huge raw damage bonuses.</p><p>Charging on interruption, counter recursion, stored ranged results, cancel/replace rules, preparation swaps and action chaining require prototype contracts. No catalogue or numeric pass is completed here.</p><h2 id="batch-06-numeric-test-scope" tabindex="-1">Batch 06 numeric test scope <a class="header-anchor" href="#batch-06-numeric-test-scope" aria-label="Permalink to &quot;Batch 06 numeric test scope&quot;">​</a></h2><p>The <a href="/Syrolands-Public/en/game-design/combat/numeric-prototype.html">three-weapon profile</a> assigns Experimental test values for Longsword, Spear and War Hammer. Its phase, resource, cadence, Flow, martial Familiarity and preparation rules apply only to that future test. Earlier examples remain historical alternatives outside this profile; no final balance, gameplay implementation or spell-number assignment follows.</p>',26)])])}const u=e(n,[["render",o]]);export{h as __pageData,u as default};
